class EnrollmentRequest(BaseModel):
    token: str = Field(
        ..., description="The join token, which is this request's only credential."
    )
    name: str = Field(..., min_length=1)
    publicKey: str = Field(
        ...,
        description="The agent's identity public key. The private half stays on\nthe node; sending it would defeat the point of per-node\nsealing.\n",
    )
    signingPublicKey: str = Field(
        ...,
        description="The agent's Ed25519 identity public key, recorded as\n`Node.signingPublicKey` and used to verify later address\nannouncements.\n",
    )
    tokenPublicKey: str = Field(
        ...,
        description="Base64 of the agent's raw Ed25519 token public key, recorded\nas `Node.tokenPublicKey` and listed in the trust bundle. The\nagent generated the pair; the private half stays on it.\n",
    )
    url: AnyUrl | None = Field(
        None,
        description="Where other hosts reach this agent — its `advertiseUrl`,\nconfigured or derived (`agent.yaml`, `GET /v1/node`). Becomes\n`Node.url`. The agent sends it because the agent knows which\ninterface it used to reach this root; a root deriving it from\nthe request's source address would be right on a flat mesh\nnetwork and wrong behind anything else.\n",
    )
    agentVersion: str | None = None
    os: Os | None = None
    arch: Arch | None = None
    devices: list[ComputeDevice] | None = None


class ControlStatus(BaseModel):
    role: NodeRole
    epoch: int = Field(
        ...,
        description='Monotonic generation of the control root. Incremented by\npromotion, and the whole of the fencing mechanism: agents\nrefuse a lower epoch, so a superseded root cannot command\nanything that has already heard from its successor.\n',
        ge=1,
    )
    appliedIndex: int = Field(
        ..., description='The highest log index this process has applied.', ge=0
    )
    firstAvailableIndex: int | None = Field(
        None,
        description='Oldest index still in the log after compaction. A standby\nwhose position predates this cannot catch up by reading the\nlog and must take a snapshot instead.\n',
    )
    standbys: list[StandbyStatus] | None = Field(
        None,
        description='Present on the active root. **This is the "is failover safe\nright now" answer** — a standby trailing the active root\ncannot be promoted without losing the difference, and an\noperator should see that before a failure rather than during\none.\n\nSince 2026-10-08, the node that holds the `standby` grant, from\napplied state; the `standbyUrls` setting is no longer read.\n',
    )
    activeUrl: AnyUrl | None = Field(
        None, description='Where the active root is, as reported by a standby.'
    )
    initialized: bool | None = None


class LogEntry(BaseModel):
    """
    One control-state change. Applied state is a deterministic
    function of the entries applied so far, which is the property
    that makes a standby's state comparable to the active root's —
    and the property a later move to consensus would depend on.

    """

    index: int = Field(
        ...,
        description='Gapless and monotonic, assigned by the active root alone.\n**The only ordering there is.**\n',
        ge=1,
    )
    epoch: int = Field(
        ...,
        description='The control-root generation that appended this entry. A\nstandby rejects entries from an epoch below the highest it\nhas seen, which fences a superseded root out of the log as\nwell as out of the agents.\n',
    )
    op: LogOp
    payload: dict[str, Any] | None = Field(
        None, description='Operation-specific. Shape follows `op`.'
    )
    at: AwareDatetime | None = Field(
        None,
        description='**Informational only, never used for ordering.** Recorded so\nan operator can read the log; deliberately not load-bearing,\nwhich is what keeps clock skew between buildings out of the\ncorrectness argument.\n',
    )


class SnapshotSite(BaseModel):
    """
    One Job Site in the registry (J19).
    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: str = Field(
        ...,
        description="A site's id: random, given by the root at enrollment, and fixed for\nthat enrollment. A machine that joins again gets a new one. Never a\nmachine's name, which is only its `label`.\n",
        pattern='^s-[a-z2-7]{26}$',
    )
    label: str = Field(
        ...,
        description="What people call the site, the machine's name by default. Not unique, not an identifier.",
        max_length=63,
        min_length=1,
        pattern='^[A-Za-z0-9][A-Za-z0-9_.-]*$',
    )
    owner: str = Field(..., description="The owner's person id.")
    tokenPublicKey: str
    enrolledAt: AwareDatetime
    hostNode: str | None = None
    devGrants: list[SiteDevGrant] | None = Field(None, max_length=64)


class Person(BaseModel):
    """
    Someone the operator lets sign in to apps (C2). Not an operator:
    a person's sign-in opens their apps and nothing in the hub.

    """

    id: str = Field(..., description='Stable; the `sub` in their ID tokens.')
    name: str = Field(
        ..., description='What they sign in with. Unique, compared case-folded.'
    )
    displayName: str | None = None
    email: str | None = Field(
        None,
        description='Optional, and unique compared case-folded. Given to an app that\nasks for the `email` scope, with `email_verified: false`: Eugene\nsends no mail and has proved nothing about it. Some apps (Open\nWebUI) identify people by it (C4).\n',
    )
    apps: list[str] | None = Field(
        None,
        description='The `clientId`s they may sign in to. Null is every app on the install.',
    )
    permissions: list[PersonPermission] | None = Field(
        None,
        description="Exactly these permissions (J77). Null is the install's defaults,\nthe root's settings `peopleMayAddJobSites` and\n`peopleMayUseJobSites`, so changing a default changes everyone\nleft on it.\n",
        max_length=16,
    )
    permissionsInEffect: list[PersonPermission] | None = Field(
        None,
        description="What applies now, from `permissions` or, when it is null, the install's defaults.",
    )
    disabled: bool
    createdAt: AwareDatetime
    passwordChangedAt: AwareDatetime


class PersonList(BaseModel):
    people: list[Person]
    operatorName: str | None = Field(
        None,
        description='The name the owner signs in with, once the install has people.',
    )


