class Node(BaseModel):
    """
    One host in this install.

    Identified by an operator-supplied `name`, consistent with
    components and runtimes — but its *identity* is `publicKey`. A
    name is a label an operator can read; the keypair is what makes
    a node the same node after a restart, and what a secret is sealed
    to.

    """

    name: str = Field(
        ...,
        description='Operator-supplied, unique per install. Used in\n`Runtime.node`, `RuntimePlacementSpec.node`, and anywhere a\nplacement has to be named.\n',
        min_length=1,
    )
    url: AnyUrl | None = Field(
        None,
        description="Where this node's agent is reachable — from this root, and from\na gateway sending a lifecycle action to the agent that owns a\nruntime. Recorded verbatim from `EnrollmentRequest.url`; the\nagent is the one that knows how it reached this root, and this\nroot does not guess from a source address.\n",
    )
    role: NodeRole
    reachable: bool = Field(
        ...,
        description="Whether the control root could reach this node's agent on its\nlast attempt. False means `down`, not `out` — see this\ndocument's description. Nothing is reassigned on the strength\nof this field alone.\n",
    )
    publicKey: str | None = Field(
        None,
        description="The node's identity public key, generated at enrollment. The\nprivate half never leaves the node, which is what makes\nper-node sealing meaningful: a secret sealed to this key can\nbe read by this host and by the recovery recipient, and by\nnothing else.\n",
    )
    signingPublicKey: str | None = Field(
        None,
        description="The node's **Ed25519** public key, used for one thing: to\nverify that a `PATCH /v1/nodes/{name}` really came from this\nnode. `publicKey` cannot do it — that one is X25519 and\nexists so secrets can be sealed to the node — and a key that\nboth seals and signs is a key whose compromise costs twice.\n\nAbsent on a node enrolled before nodes had a signing\nidentity. Such a node cannot re-advertise and must re-enroll;\nsurfaced here rather than inferred from a 401.\n",
    )
    tokenPublicKey: str | None = Field(
        None,
        description="Base64 of this node's raw Ed25519 **token** public key, the\nkey its tokens are signed with. It is listed in the trust\nbundle as `node:<name>`. The private half was generated on\nthe node and has never been anywhere else. A third key,\nseparate from `publicKey` and `signingPublicKey`, because\neach key does one job.\n",
    )
    grants: list[TrustGrant] | None = Field(
        None,
        description="What this node's key may issue, as the trust bundle lists it:\n`node`, plus `gateway` when the join token that enrolled it\nsaid so. Given by the join token, never claimed by the node.\nA Job Site is not a node: it has its own registry and key\n(`/v1/sites`, J19). A node enrolled with `files` before that\n(slices 1 and 2) still replays, as a **retired** node: it is\nin no listing and no trust bundle, and nothing it signs is\naccepted.\n",
    )
    owner: str | None = Field(
        None,
        deprecated=True,
        description='Written only for a node enrolled with `files` before slice\n2b.1, and kept so its log and snapshots still replay. `null`\nfor every other node.\n',
    )
    trustBundleVersion: int | None = Field(
        None,
        description='The trust bundle version this node reported holding on the\nlast probe. A value below the current one is a node that has\nnot yet taken a revocation or a rotation. Observation, not\napplied state, so never replicated; `null` until probed.\n',
    )
    advertiseSequence: int | None = Field(
        None,
        description='The highest announcement sequence accepted from this node. A\n`PATCH /v1/nodes/{name}` at or below it is a replay and is\nrefused. Applied state, so a promoted standby refuses the\nsame replays this root would.\n',
        ge=0,
    )
    lastSeenEpoch: int | None = Field(
        None,
        description='The highest control-root epoch this node has acknowledged. A\nvalue below `ControlStatus.epoch` is the visible symptom of a\nnode that was partitioned during a promotion — bounded,\nself-healing, and deliberately surfaced rather than hidden.\n',
        ge=0,
    )
    agentVersion: str | None = None
    os: Os | None = None
    arch: Arch | None = None
    devices: list[ComputeDevice] | None = Field(
        None,
        description='What this host can compute on. **This is the cross-host\nhardware inventory M3 deferred**, and it lands here exactly\nas M3 predicted: *"building a real inventory is topology work\nand belongs to the agent if it belongs anywhere."*\n\nThe library\'s fit surface already takes a hardware override\nand reports which host it measured, so multi-host quant\nguidance works as soon as these exist. Reported, not acted\non — deciding *which* node should host a model is lifecycle\npolicy, which is M6.\n',
    )
    enrolledAt: AwareDatetime | None = None
    lastSeenAt: AwareDatetime | None = None
    lastError: str | None = Field(
        None,
        description='Why the last probe of this node did not come back with an\nidentity, in the probe client\'s words -- an HTTP status and\nthe body\'s title, or a transport error. `null` when the node\nanswered, and when nothing has polled yet.\n\nAdded 2026-09-15 because `reachable: false` on its own sent an\noperator looking at enrollment, keys and firewalls when the\ncause was a worker refusing this root\'s tokens as "not yet\nvalid (iat)" over half a second of clock skew. The probe\nclient had the reason the whole time; this surface dropped\nit. Observation, not applied state: a standby has not seen\nwhat this root saw, so it is never replicated.\n',
    )


class InputAudioContentPart(BaseModel):
    """
    A recording the model hears, in OpenAI's chat shape. Carried only
    to a model whose backend confirms audio input
    (`capabilities.audioInput`); nothing else is asked, so a model
    that cannot hear it never answers as though it had.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    type: Literal['input_audio']
    input_audio: InputAudio


class ChatLogprobs(BaseModel):
    """
    The chosen tokens' log probabilities, OpenAI's shape (P2c). Asked
    for with `logprobs` (and `top_logprobs` for alternatives). Streamed,
    each frame carries the entries for its own tokens.

    """

    content: list[ChatTokenLogprob] | None = None
    refusal: list[ChatTokenLogprob] | None = None


class ConfigField(BaseModel):
    """
    UI-renderable description of a single editable config field.

    """

    key: str = Field(
        ...,
        description='Stable machine-readable id, dot-separated for grouping\n(e.g. `"adapter.modelId"`).\n',
    )
    label: str = Field(..., description='Human-readable label for the UI.')
    description: str | None = Field(
        None, description='One-sentence explanation suitable for non-programmers.'
    )
    category: str = Field(
        ...,
        description='Group key for UI tabbing or sectioning (e.g. `"adapter"`,\n`"logging"`, `"network"`). Mapped to a display label via\n`ConfigSchema.categories`.\n',
    )
    valueType: ConfigValueType
    default: Any | None = Field(
        None,
        description='Default value if unset. Type matches `valueType`. Omitted\nfor fields with no default.\n',
    )
    enumValues: list[str] | None = Field(
        None, description='Allowed values when `valueType == enum`.'
    )
    suggestions: list[str] | None = Field(
        None,
        description="Discovery-time hints — values the operator might want\nbut which AREN'T enforced by validation. UIs render\nstring-typed fields with non-empty `suggestions` as a\ncombobox (free-text input with a dropdown of suggestions)\nrather than a strict dropdown. Use when the set of\nvalid values is large, partially-discoverable, or\nextends beyond what the component knows at the moment\n(e.g. local LLM model lists that update when the operator\npulls a new model). Distinct from `enumValues`:\nsuggestions are advisory, enumValues are mandatory.\n",
    )
    componentKindHint: ComponentKind | None = Field(
        None,
        description="Declarative rendering hint: this field references a peer\ncomponent of the given kind. UIs render any kind-hinted\nfield as a dropdown sourced from the agent's\n`/v1/components` (filtered by kind), with `(off)` as the\nfirst option (saves an empty string). For single-instance\nkinds (memory, identity, etc.) the dropdown UX collapses\nto effectively a toggle; for multi-instance kinds\n(inference-driver) the operator picks one. Pairs with a\nstring/url `valueType` — the saved value is still the\npeer's URL, the hint only changes how the UI looks it up.\nAvoids the OpenClaw trap of duplicating topology into\nfree-text URL fields the operator has to type by hand.\n",
    )
    enumLabels: list[str] | None = Field(
        None,
        description='Optional human-readable display labels paired one-to-one\nwith `enumValues`. UIs that render an enum as a dropdown\nshould show `enumLabels[i]` while still submitting\n`enumValues[i]` as the saved value. When omitted (or\nshorter than `enumValues`), UIs fall back to the raw\nvalue as the label. Useful where the stored key is\nmachine-friendly but the user-facing label isn\'t —\ne.g. `claude_subscription` saved, "Claude (Pro/Max)"\nshown.\n',
    )
    sensitive: bool | None = Field(
        False,
        description='If true, the value is redacted (`"<redacted>"`) in\n`ConfigDocument` responses but is accepted in\n`ConfigUpdateRequest`. Use for API keys, passwords, etc.\n',
    )
    required: bool | None = Field(
        False,
        description='If true, the component will refuse to start without this\nfield set (either in config or via env var fallback).\n',
    )
    minimum: float | None = Field(
        None, description='Validation hint for `integer` / `number` fields.'
    )
    maximum: float | None = Field(
        None, description='Validation hint for `integer` / `number` fields.'
    )
    pattern: str | None = Field(
        None, description='Regex validation hint for `string` / `url` / `file_path`.'
    )
    requiresRestart: bool | None = Field(
        False,
        description='If true, changes to this field via PATCH are accepted and\nstored but do not take effect until the component process\nrestarts. The UI should warn before submitting.\n',
    )
    showWhen: ConfigFieldShowWhen | None = Field(
        None,
        description="Conditional-rendering hint. When set, the UI should only\nrender this field when another field's current value matches\nthe condition. Used to hide adapter-specific fields\n(e.g. `openaiApiKey`) when a different adapter is selected.\nThe component still validates and stores the field\nregardless of UI visibility.\n\n**A field must be shown wherever the component reads it**\n(2026-09-30): a condition narrower than the code that reads the\nvalue hides a setting while it is in effect. The referenced\nfield's value is its effective one -- its `default` when the\ndocument leaves it out.\n",
    )
    defaultSource: str | None = Field(
        None,
        description='Where `default` comes from, as a sentence, when it is not the\ncomponent\'s own built-in value -- e.g. "Set by this container\nimage, through EUGENE_PLEXUS_AGENT_DEFAULT_UPDATE_CHANNEL." A\ndefault from the environment is shown in the UI and never\nwritten to the component\'s file. Absent for a built-in default.\n\n**Settings never lie** (2026-09-30, Troy: fundamental). The five\nproperties from here to `managedBy` exist so a widget can show\nexactly the value in effect, and say so when that value is a\ndefault, unset, derived, inherited, not yet in effect or set by\nsomething else -- never a stand-in that looks like a choice.\n',
    )
    unsetMeans: str | None = Field(
        None,
        description='What this field does while it holds no value, as a sentence a\nperson reads -- "No cap: an answer runs until the model\nfinishes." -- shown where the control would otherwise be empty,\nor show a default the component is not using. Present on every\nfield without a `default` whose absence means something, and on\nany field whose unset value means something other than\n`default` right now. For a list, it says what the EMPTY list\nmeans. May be computed per request, so it can name what an\nunset value resolves to on this machine.\n',
    )
    unsetResolvesTo: Any | None = Field(
        None,
        description="The value an unset field stands for right now, typed like the\nfield, when the component can know it: a provider's own\naddress, the advertise address derived from the route to the\ncontrol root. Absent when it cannot be known here or depends on\neach request. Never sent for a `sensitive` field.\n",
    )
    pendingRestart: bool | None = Field(
        False,
        description='The value in `GET /v1/config` is saved but not in effect: this\n`requiresRestart` field was changed since the process started,\nand the process still runs on the value it started with\n(`inEffect`). Cleared by the restart.\n',
    )
    inEffect: Any | None = Field(
        None,
        description='With `pendingRestart`, the value the running process uses,\ntyped like the field. Never sent for a `sensitive` field.\n',
    )
    managedBy: str | None = Field(
        None,
        description='The field is written by another part of the install, which\nrewrites it: a sentence saying which, and where to change it\ninstead -- "Set by this machine\'s agent from the runtime this\ndriver fronts; change the runtime." UIs show it read-only, and\n`PATCH` refuses it.\n',
    )
    status: ConfigFieldStatus | None = Field(
        None,
        description="What this field's value is doing right now, when the value alone\ndoes not say it: a mode this machine cannot carry out, a value\nnot yet acted on. Shown beside the control.\n",
    )


class ConfigSchema(BaseModel):
    """
    UI-renderable description of every editable config field this
    component accepts. Returned by `GET /v1/config/schema`. UIs use
    this to render a generic config editor without component-specific
    code.

    """

    component: str = Field(
        ..., description='Component identifier (e.g. `"inference-driver"`).'
    )
    fields: list[ConfigField]
    categories: dict[str, str] | None = Field(
        None,
        description='Map from category key (used in `ConfigField.category`) to\na human-readable section label. Optional; UIs may fall back\nto the raw key.\n',
    )


class DirectoryListing(BaseModel):
    """
    One directory on the component's own host, listed for a picker.

    Returned by `GET /v1/directories` on the library (whose host
    holds the model roots) and on the agent (whose host holds a
    path mapping's `to`, and any engine binary an operator points
    at). The same shape on both, because the UI has one picker and
    the only thing that differs is which machine's disk it is
    looking at — which is why `host` is on the response.

    This is the endpoint behind the promise `path_list` has carried
    since M2: *"an add/remove list of directory pickers"*. It lists
    what an operator could already type into a path field, on
    request, to the strongest credential there is; it is not a new
    capability and it is not a file browser.

    """

    host: str = Field(
        ...,
        description='The machine whose disk this is. On a multi-host install the\nanswer to "browse" is frequently a machine other than the\none the browser is on.\n',
    )
    path: str | None = Field(
        None,
        description='The directory listed, absolute and as this host spells it.\nAbsent when no `path` was asked for, in which case `entries`\nare the places to start from — every drive on Windows, `/`\non POSIX, and the home directory.\n',
    )
    parent: str | None = Field(
        None,
        description='The directory above `path`, so a picker can go up without\ndoing path arithmetic in a browser. Absent at a filesystem\nroot and when `path` is absent.\n',
    )
    entries: list[DirectoryEntry] = Field(
        ...,
        description='Sorted by name, directories first. Entries this component\nmay not read are omitted rather than failing the listing.\n',
    )


class LogPage(BaseModel):
    entries: list[LogEntry] = Field(
        ..., description='Oldest first, gapless, strictly increasing `index`.'
    )
    appliedIndex: int = Field(
        ...,
        description="The active root's own applied index, so a caller can compute its lag.",
    )
    firstAvailableIndex: int | None = Field(
        None,
        description='Reported on every page so a standby learns it has fallen\nbehind compaction *before* it tries to read a gap.\n',
    )


class Snapshot(BaseModel):
    """
    Applied state as of `index`, for bootstrapping a standby or
    recovering one that fell behind compaction.

    Carries the replication set and nothing else. The passphrase
    exists only in the operator's head; per-component secrets are
    sealed on the hosts that read them and never travel here.

    **The governing rule, learned by implementing it:** a snapshot
    has to be able to reproduce exactly what the log produces,
    because it *is* the log's compacted head. **Every** `LogOp` value
    must have somewhere to land here, or compaction
    silently discards the state that op wrote — and the loss shows
    up at a promotion rather than at the compaction. Adding an op
    means checking this schema can hold its effect.

    **`Node.reachable` in a snapshot is not an observation.** It is
    required by that schema and a snapshot carries no observations,
    so it is always `false` here and a reader must not treat it as a
    report about the host. Reachability, `lastSeenAt` and
    `lastSeenEpoch` belong to whichever root did the polling; see
    `GET /v1/nodes`.

    """

    clientAdmission: dict[str, Any] | None = Field(
        None,
        description='Durable logical clock and per-key admission buckets; replayed verbatim with leases and rolling-window charges.',
    )
    clientKeys: list[ClientKey] | None = None
    index: int
    epoch: int
    nodes: list[Node] | None = None
    components: list[ComponentPlacement] | None = None
    runtimes: list[RuntimePlacementSpec] | None = Field(
        None,
        description='Runtime **declarations** — what should be running where —\nand deliberately not `RuntimePlacement`, which is the\nreporting shape and carries no `spec`.\n\n§4 of the design requires "declared runtimes" to survive,\nand a placement without its spec is not a declaration: a\npromoted standby holding one would know a runtime\'s name and\nnothing about the model path or flags it launches with.\n`node` is always present here even though the schema allows\nit to be omitted elsewhere; a snapshot has no "the node the\ncontrol root runs on" default to fall back on, because the\nroot that reads it may not be the root that wrote it.\n',
    )
    config: dict[str, Any] | None = Field(
        None,
        description="The control root's own applied configuration.\n\nReplicated because `patchConfig` is one of the ops, so\nconfig *is* control state — and a snapshot that dropped it\nwould lose every config change made before the last\ncompaction. A promoted standby that came up without\n`standbyUrls` would silently have no standbys of its own,\nwhich is the failure mode where the second failover is the\none that hurts. (Since 2026-10-08 the standby is the node with\nthe `standby` grant, which is in `nodes`, and `standbyUrls` is\nno longer read.)\n",
    )
    signingKeyId: str | None = Field(
        None,
        description="Names the current generation of this root's token key. Not a\nsecret.\n",
    )
    revokedSessions: list[RevokedSession] | None = Field(
        None,
        description='Sessions signed out and not yet expired, as `revokeSession`\nwrote them. The trust bundle carries the same list.\n',
    )
    salt: str | None = Field(
        None,
        description='The Argon2id salt. Replicated because without it the same\npassphrase derives a different key, and a standby that cannot\nderive the master key cannot be promoted.\n',
    )
    passphraseVerifier: str | None = Field(
        None,
        description='Lets a standby authenticate the operator at promotion without\nholding the master key.\n',
    )
    sealedRecoveryKey: str | None = Field(
        None,
        description="The recovery recipient, sealed under the passphrase-derived\nkey. Replicated so a promoted standby can still reach a dead\nnode's secrets; useless to anyone without the passphrase.\n",
    )
    sealedSigningKey: str | None = Field(
        None,
        description="This root's token key, sealed under the passphrase-derived\nkey: what signs operator sessions, exchanged tokens and client\nkeys. It never leaves a root in any other form.\n\nReplicated so a promoted standby signs with the same key and\nnobody has to sign in again or reissue a client key. It is\n**sealed** because a snapshot is a file on a second host; the\nstandby has the salt and the verifier but no master key until\nthe operator supplies the passphrase at promotion, which is\nexactly the moment it needs to open this.\n",
    )
    rootTokenPublicKey: str | None = Field(
        None,
        description='Base64 of the raw public half of the above, in the clear, so a\nroot can publish a bundle naming it without unsealing\nanything.\n',
    )
    sealedControlKey: str | None = Field(
        None,
        description="The control root's own identity private key, sealed under\nthe passphrase-derived key. Its public half is what nodes\nrecord at enrollment as `controlPublicKey` and check epoch\nchanges against, so a promoted standby that generated a\n*fresh* identity would be rejected by every enrolled node.\nReplicating it is what makes promotion a change of host\nrather than a change of identity.\n",
    )
    controlPublicKey: str | None = Field(
        None,
        description='The public half of the above, carried in the clear so a\nstandby can report the identity it would assume without\nholding the passphrase.\n',
    )
    people: list[SnapshotPerson] | None = Field(
        None,
        description='The people who may sign in to apps, as `putPerson`,\n`setPersonPassword` and `deletePerson` left them, with their\nArgon2id verifiers: as `passphraseVerifier` is here, and for the\nsame reason (a promoted standby signs people in).\n',
    )
    sites: list[SnapshotSite] | None = Field(
        None,
        description='The Job Site registry (J19), as `enrollSite`, `removeSite`, `setSiteHost` and `setSiteDevGrants` left it.',
    )
    nodeHelpers: list[dict[str, Any]] | None = Field(
        None,
        deprecated=True,
        description='Read from snapshots written before slice 2b.1, and ignored. The operator-managed node folders retired (J20).',
    )
    oidcClients: list[SnapshotOidcClient] | None = None
    oidcKeys: list[SnapshotOidcKey] | None = Field(
        None,
        description="The provider's RSA keys, newest first, each sealed under the\npassphrase-derived key as `sealedSigningKey` is.\n",
    )
    revokedSignIns: list[RevokedSession] | None = Field(
        None,
        description='Sign-ins revoked at `/oidc/revoke` and not yet expired, by their `jti`.',
    )


class SiteSummary(BaseModel):
    """
    What a job site holds, as the site itself reports it in each poll. The
    root keeps it as a cache: it answers Workbench's listings from it, and
    the site checks every call against its own copy again (rule 2 of §3.3).

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    owner: str = Field(
        ...,
        description='The person the site pinned as its owner at its join.',
        max_length=64,
        min_length=1,
    )
    ownerInDevMode: bool = Field(
        ...,
        description="The site's owner lets Eugene's owner in while Eugene is in dev mode (J6e).",
    )
    folders: list[SiteFolder] | None = Field(
        None,
        description='From a site before 2b.3b, which reports folders with their paths. A newer site reports `workspaces` instead.',
        max_length=64,
    )
    workspaces: list[SiteWorkspace] | None = Field(
        None,
        description="Every linked person's workspaces, by id and name, never path (2b.3b, J76). The root shows each person only their own and those shared with them.",
        max_length=512,
    )
    servers: list[SiteServer] = Field(..., max_length=96)
    access: list[SiteAccess] = Field(
        ...,
        description="Who may use the local servers' tools. Folders carry their own people.",
        max_length=2048,
    )
    links: list[SitePersonLink] | None = Field(
        None,
        description="The people linked to an OS account on this machine (§2.2, J27), and\nwhether each one's worker is connected now. A linked person's calls\nrun as their own account; anyone else's run in the owner's worker,\nas the owner, confined to the folder (J27).\n",
        max_length=256,
    )
    linkPage: str | None = Field(
        None,
        description="Where a person links their account, on the machine itself: the\nagent's loopback link page on a Windows service install. Null where\nlinking is the elevated one-liner (a Linux system install, J36) or\nwhere only the installing person is served (a per-user install, J38).\n",
        max_length=256,
    )
    sharing: bool | None = Field(
        None,
        description='Whether this site can serve anyone but its owner. False on macOS,\nwhich has no folder boundary yet (§2.6). Absent means true.\n',
    )
    signing: SiteSigning | None = None
    commands: SiteCommands | None = None


class JobSite(BaseModel):
    """
    One of the signed-in person's sites, as Workbench's Job sites page shows
    it: one they own, or since 2b.3b one they are linked to (`role`). A
    linked person who does not own it sees only their own: their workspaces,
    their link, their keys' state; no folders of others, no servers.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    id: str = Field(
        ...,
        description="A site's id: random, given by the root at enrollment, and fixed for\nthat enrollment. A machine that joins again gets a new one. Never a\nmachine's name, which is only its `label`.\n",
        pattern='^s-[a-z2-7]{26}$',
    )
    label: str = Field(
        ...,
        description="What people call the site, the machine's name by default. Not unique, not an identifier.",
        max_length=63,
        min_length=1,
        pattern='^[A-Za-z0-9][A-Za-z0-9_.-]*$',
    )
    role: JobSiteRole | None = None
    workspaces: list[JobSiteWorkspace] | None = Field(
        None,
        description="This person's own workspaces there, and for the owner whom each is\nshared with, by id and name, as the site last reported them (2b.3b).\nPaths are read live (`/oidc/job-sites/{site}/workspaces/list`, J76).\n",
    )
    online: bool
    ready: bool
    reason: str | None = None
    account: str | None = Field(
        None,
        description="The kind of OS account the site host itself runs in. Tools run in each person's worker (`links`).",
    )
    links: list[SitePersonLink] | None = Field(
        None,
        description="The people linked to an OS account on that machine, and whether each one's calls can run now (§3.2).",
    )
    linkPage: str | None = Field(
        None,
        description='Where a person links their account on that machine, when it offers a page (a Windows service install).',
    )
    sharing: bool | None = Field(
        None,
        description='Whether the site can serve anyone but its owner (false on macOS). Absent means true.',
    )
    lastContactAt: AwareDatetime | None = None
    hostNode: str | None = Field(
        None, description='The node that hosts it (J32), for display.'
    )
    folders: list[JobSiteFolder] = Field(
        ...,
        description='The folders registered on it, which its one file server offers by name (J6g), and who may use each.',
    )
    servers: list[JobSiteServer] = Field(
        ..., description='The local servers a machine administrator added at it.'
    )
    ownerInDevMode: bool | None = Field(
        None,
        description="Whether the site lets Eugene's owner in while Eugene is in dev mode (J6e). Null until the site has reported.",
    )
    signing: SiteSigning | None = Field(
        None,
        description="Whether the site checks its owner's changes with the owner's own key (J14a). Absent from a site older than J14a.",
    )
    commands: SiteCommands | None = Field(
        None,
        description='Whether the machine runs commands from Workbench (2b.4, J89). Absent from a site older than 2b.4.',
    )


class JobSiteList(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
    )
    sites: list[JobSite]
    installMode: InstallMode
    canInvite: bool = Field(
        ...,
        description="Whether this root knows the address a machine joins through: the\nentry point's nodes name, or the address Eugene's owner set\n(`siteJoinUrl` in the root's settings). It does not need the public\nroute: a machine on the root's own network joins through its LAN\naddress (J31).\n",
    )


class NodeList(BaseModel):
    nodes: list[Node]


class SiteReport(BaseModel):
    """
    What a site host reports in each poll (`POST /v1/sites/poll`). The root
    keeps it as a cache for listings; the site checks every call against
    its own copy again (rule 2 of remote-nodes.md §3.3).

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    protocol: SiteHostProtocol
    hostVersion: str | None = Field(None, max_length=64)
    ready: bool
    reason: str | None = Field(None, max_length=1024)
    account: str | None = Field(
        None,
        description="The kind of OS account the site host itself runs in. Since 2b.2 the\nsite's tools run in each person's worker, as `SiteSummary.links`\nsays, and never in this account.\n",
        max_length=256,
    )
    site: SiteSummary | None = None


class MessageContent1(
    RootModel[
        list[
            TextContentPart | ImageContentPart | InputAudioContentPart | FileContentPart
        ]
    ]
):
    root: list[
        TextContentPart | ImageContentPart | InputAudioContentPart | FileContentPart
    ] = Field(
        ...,
        description="Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: the gateway's `maxImagesPerRequest`\nper request (12 by default, at most 64, counted across the whole\nconversation), 5 MiB decoded each, 10 MiB decoded total, 16 million\npixels each, maximum dimension 8192. The inference-driver enforces\nthe ceiling of 64; the gateway enforces the setting.\n\nAudio (`input_audio`, WAV or MP3) and files (`file`, PDF) are\ninline too: at most 10 MiB decoded each, and every attachment in\nthe request together -- images, audio and files -- at most\n11 MiB decoded, which is what fits in the 16 MiB JSON body once\nbase64 has grown it by a third. Attachments ride on user messages\nonly. Remote URLs are never fetched, and a `file_id` is refused:\neach names a store this install does not have.\n",
        min_length=1,
    )


class Message(BaseModel):
    """
    A single message in a conversation. Deliberately close to the
    OpenAI / Anthropic chat message format so drivers don't have to
    re-shape on every hop.

    """

    role: Role
    content: str | MessageContent1 | None = Field(
        None,
        description="Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: the gateway's `maxImagesPerRequest`\nper request (12 by default, at most 64, counted across the whole\nconversation), 5 MiB decoded each, 10 MiB decoded total, 16 million\npixels each, maximum dimension 8192. The inference-driver enforces\nthe ceiling of 64; the gateway enforces the setting.\n\nAudio (`input_audio`, WAV or MP3) and files (`file`, PDF) are\ninline too: at most 10 MiB decoded each, and every attachment in\nthe request together -- images, audio and files -- at most\n11 MiB decoded, which is what fits in the 16 MiB JSON body once\nbase64 has grown it by a third. Attachments ride on user messages\nonly. Remote URLs are never fetched, and a `file_id` is refused:\neach names a store this install does not have.\n",
    )
    toolCalls: list[dict[str, Any]] | None = Field(
        None,
        description="On an **assistant** message: the tool calls the model made,\nin OpenAI's `{id, type, function: {name, arguments}}` shape.\n\nDeliberately loose here. This is the *shared* schema, so a\ntightly-typed copy would be a third definition of the same\nobject alongside the gateway's and the driver's, and the one\nplace all three must agree is the wire format, which is\nOpenAI's and not ours to restate. The two API documents\ncarry the strict shapes.\n",
    )
    toolCallId: str | None = Field(
        None,
        description='On a **tool** message: which call this is the result of.\n`content` is the result, serialized by the caller.\n',
    )
    reasoning: str | None = Field(
        None,
        description="On an **assistant** message: the reasoning the model produced\nfor that turn, as the backend reported it separately from\n`content` (`reasoning_content` on llama.cpp, `reasoning` on\nvLLM). Handed back so the next turn of a tool loop reaches\nthe model with its own earlier thinking.\n\n**Load-bearing rather than decorative, and measured:**\nllama.cpp b10948 renders a history turn's reasoning into the\nprompt for templates that preserve it (Qwen3, gpt-oss) --\nthe same tool-loop request was 172 prompt tokens without it\nand 184 with a twelve-token canary. Dropped here, a model\nresuming a tool loop has forgotten why it called the tool.\n\nAbsent on every other role, and an adapter whose backend\nhas no such channel (the agentic CLIs, a hosted OpenAI\nendpoint) omits it upstream rather than inventing one.\n",
    )
    timestamp: AwareDatetime | None = Field(
        None, description='When the message was produced. Server-assigned if omitted.'
    )
